create table if not exists public.consoles (id bigint primary key,running boolean not null default false,started_at timestamptz,elapsed_ms bigint not null default 0,final_cost numeric not null default 0,controllers integer not null default 1 check (controllers between 1 and 4));
insert into public.consoles(id) values(1),(2),(3),(4),(5) on conflict(id) do nothing;
create table if not exists public.sessions(id bigint generated by default as identity primary key,console_id bigint not null references public.consoles(id),controllers integer not null check(controllers between 1 and 4),duration_ms bigint not null,amount numeric not null,created_at timestamptz not null default now());
alter table public.consoles enable row level security; alter table public.sessions enable row level security;
drop policy if exists consoles_select on public.consoles; drop policy if exists consoles_update on public.consoles; drop policy if exists sessions_select on public.sessions; drop policy if exists sessions_insert on public.sessions;
create policy consoles_select on public.consoles for select to authenticated using(true); create policy consoles_update on public.consoles for update to authenticated using(true) with check(true); create policy sessions_select on public.sessions for select to authenticated using(true); create policy sessions_insert on public.sessions for insert to authenticated with check(true);
